// Pin map for the Xbot remote (nRF52832). Arduino pin numbers equal P0.x on
// this variant. All keys are dome switches to GND with internal pull-ups.
//
// Pins deliberately avoided:
//   P0.00/P0.01  32.768 kHz crystal
//   P0.09/P0.10  NFC pads
//   P0.17/P0.19  driven as LED outputs by the board variant at start-up
//   P0.20        bootloader DFU strap (low at reset = stay in bootloader)
//   P0.21        nRESET
//   P0.22        bootloader factory-reset strap
//   P0.06/P0.08  default UART
#pragma once
#include <Arduino.h>

const uint8_t PIN_KEY_UP     = 11;
const uint8_t PIN_KEY_DOWN   = 12;
const uint8_t PIN_KEY_LEFT   = 13;
const uint8_t PIN_KEY_RIGHT  = 14;
const uint8_t PIN_KEY_CENTRE = 15;
const uint8_t PIN_KEY_POWER  = 16;
const uint8_t PIN_KEY_REC    = 27;

// Over-the-air contract between the remote and the camera.
//
// One notify characteristic, fixed 4 bytes:
//   [0] held    bitmask of keys held right now (KEY_* bits)
//   [1] clicks  one-shot events for toggle keys (centre, record, power);
//               set in exactly one report per press, act on it once
//   [2] seq     increments on every report
//   [3] batt    coin cell level 0..100 %
//
// While any key is held the report repeats every REPEAT_MS. The camera must
// treat missing reports for ~3x REPEAT_MS, or a disconnect, as 'all released'
// and stop the pan motor.
#pragma once
#include <stdint.h>

const uint8_t KEY_UP     = 1 << 0;
const uint8_t KEY_DOWN   = 1 << 1;
const uint8_t KEY_LEFT   = 1 << 2;
const uint8_t KEY_RIGHT  = 1 << 3;
const uint8_t KEY_CENTRE = 1 << 4;
const uint8_t KEY_POWER  = 1 << 5;
const uint8_t KEY_REC    = 1 << 6;

const uint8_t REPORT_LEN = 4;

// 128-bit UUIDs, little-endian byte order as the SoftDevice wants them.
// Service        7b3e0001-5c1d-4a8e-9f20-58626f740000
// Characteristic 7b3e0002-5c1d-4a8e-9f20-58626f740000
const uint8_t REMOTE_SVC_UUID[16] = {
  0x00, 0x00, 0x74, 0x6f, 0x62, 0x58, 0x20, 0x9f,
  0x8e, 0x4a, 0x1d, 0x5c, 0x01, 0x00, 0x3e, 0x7b};
const uint8_t REMOTE_CHR_UUID[16] = {
  0x00, 0x00, 0x74, 0x6f, 0x62, 0x58, 0x20, 0x9f,
  0x8e, 0x4a, 0x1d, 0x5c, 0x02, 0x00, 0x3e, 0x7b};

// Xbot remote firmware: scan seven keys, report them over BLE, sleep hard.
#include <Arduino.h>
#include <bluefruit.h>
#include "nrf_gpio.h"
#include "pins.h"
#include "protocol.h"

// ---- timings ----
const uint32_t SCAN_MS          = 5;      // key sample period
const uint8_t  DEBOUNCE_SAMPLES = 4;      // 20 ms stable before accepting an edge
const uint32_t REPEAT_MS        = 100;    // keep-alive while a key is held
const uint32_t POWER_HOLD_MS    = 1000;   // power key must be held this long
const uint32_t STUCK_MS         = 30000;  // key held longer than this is ignored
const uint32_t CLICK_EXPIRE_MS  = 3000;   // undelivered toggle is dropped, not sent late
const uint32_t IDLE_SLEEP_MS    = 20000;  // no key activity -> System OFF
const uint32_t BATT_PERIOD_MS   = 30000;
const uint16_t BATT_EMPTY_MV    = 2000;   // CR2032 is done around 2.0 V
const uint16_t BATT_FULL_MV     = 3000;

struct Key {
  uint8_t  pin;
  uint8_t  bit;
  bool     stable;   // debounced state, true = pressed
  bool     stuck;    // held too long, ignored until released
  uint8_t  count;    // consecutive samples that disagree with 'stable'
  uint32_t since;    // time of last debounced edge
};

static Key keys[] = {
  {PIN_KEY_UP,     KEY_UP,     false, false, 0, 0},
  {PIN_KEY_DOWN,   KEY_DOWN,   false, false, 0, 0},
  {PIN_KEY_LEFT,   KEY_LEFT,   false, false, 0, 0},
  {PIN_KEY_RIGHT,  KEY_RIGHT,  false, false, 0, 0},
  {PIN_KEY_CENTRE, KEY_CENTRE, false, false, 0, 0},
  {PIN_KEY_POWER,  KEY_POWER,  false, false, 0, 0},
  {PIN_KEY_REC,    KEY_REC,    false, false, 0, 0},
};
const uint8_t NUM_KEYS = sizeof(keys) / sizeof(keys[0]);

static BLEService        remoteSvc(REMOTE_SVC_UUID);
static BLECharacteristic remoteChr(REMOTE_CHR_UUID);
static BLEBas            battSvc;

static uint8_t  pendingClicks   = 0;
static uint32_t pendingSince    = 0;
static bool     powerClickFired = false;
static uint8_t  lastSentHeld    = 0;
static volatile bool dirty      = true;   // state not yet delivered to the camera
static uint8_t  seq             = 0;
static uint8_t  battPct         = 100;
static uint32_t lastActivity    = 0;
static uint32_t lastScan        = 0;
static uint32_t lastReport      = 0;
static uint32_t lastBatt        = 0;

static void queueClick(uint8_t bit, uint32_t now) {
  pendingClicks |= bit;
  pendingSince = now;
}

static uint8_t heldMask() {
  uint8_t m = 0;
  for (uint8_t i = 0; i < NUM_KEYS; i++) {
    if (keys[i].stable && !keys[i].stuck) m |= keys[i].bit;
  }
  return m;
}

static void measureBattery() {
  // Default reference is 0.6 V internal with 1/6 gain: 3.6 V full scale.
  analogReadResolution(12);
  uint32_t raw = analogReadVDD();
  uint32_t mv = raw * 3600UL / 4095UL;
  if (mv <= BATT_EMPTY_MV) {
    battPct = 0;
  } else if (mv >= BATT_FULL_MV) {
    battPct = 100;
  } else {
    battPct = (uint8_t)((mv - BATT_EMPTY_MV) * 100UL / (BATT_FULL_MV - BATT_EMPTY_MV));
  }
}

static void scanKeys(uint32_t now) {
  for (uint8_t i = 0; i < NUM_KEYS; i++) {
    Key &k = keys[i];
    bool raw = (digitalRead(k.pin) == LOW);
    if (raw == k.stable) {
      k.count = 0;
    } else if (++k.count >= DEBOUNCE_SAMPLES) {
      k.stable = raw;
      k.count = 0;
      k.since = now;
      lastActivity = now;
      if (raw) {
        if (k.bit == KEY_CENTRE || k.bit == KEY_REC) queueClick(k.bit, now);
        if (k.bit == KEY_POWER) powerClickFired = false;
      } else {
        k.stuck = false;
      }
    }

    if (k.stable && !k.stuck) {
      uint32_t heldFor = now - k.since;
      // Power needs a deliberate hold so a pocket bump cannot shut the camera down mid-game.
      if (k.bit == KEY_POWER && !powerClickFired && heldFor >= POWER_HOLD_MS) {
        powerClickFired = true;
        queueClick(KEY_POWER, now);
      }
      // A key jammed in a bag must not pan the camera forever or drain the cell.
      if (heldFor >= STUCK_MS) k.stuck = true;
    }
  }
}

static void serviceReport(uint32_t now) {
  // A toggle that could not be delivered promptly is dropped: starting or
  // stopping a recording seconds after the press would surprise the user.
  if (pendingClicks && (now - pendingSince) > CLICK_EXPIRE_MS) pendingClicks = 0;

  uint8_t held = heldMask();
  if (held != lastSentHeld || pendingClicks) dirty = true;

  bool keepAlive = (held != 0) && (now - lastReport >= REPEAT_MS);
  if (!dirty && !keepAlive) return;

  if (!Bluefruit.connected()) return;
  uint16_t conn = Bluefruit.connHandle();
  if (!remoteChr.notifyEnabled(conn)) return;

  uint8_t buf[REPORT_LEN] = {held, pendingClicks, (uint8_t)(seq + 1), battPct};
  if (remoteChr.notify(conn, buf, REPORT_LEN)) {
    seq++;
    lastSentHeld = held;
    pendingClicks = 0;
    dirty = false;
    lastReport = now;
  }
  // On failure (TX queue full) 'dirty' stays set and we retry next pass.
}

static void connectCallback(uint16_t conn_handle) {
  (void)conn_handle;
  dirty = true;  // push current state as soon as the camera subscribes
}

static void disconnectCallback(uint16_t conn_handle, uint8_t reason) {
  (void)conn_handle;
  (void)reason;
  dirty = true;
}

static void startAdvertising() {
  Bluefruit.Advertising.addFlags(BLE_GAP_ADV_FLAGS_LE_ONLY_GENERAL_DISC_MODE);
  Bluefruit.Advertising.addTxPower();
  Bluefruit.Advertising.addService(remoteSvc);
  Bluefruit.ScanResponse.addName();
  Bluefruit.Advertising.restartOnDisconnect(true);
  Bluefruit.Advertising.setInterval(32, 244);  // 20 ms fast, 152.5 ms slow
  Bluefruit.Advertising.setFastTimeout(30);
  Bluefruit.Advertising.start(0);
}

static void enterSystemOff() {
  Bluefruit.Advertising.restartOnDisconnect(false);
  Bluefruit.Advertising.stop();
  if (Bluefruit.connected()) {
    // Disconnecting tells the camera at once that nothing is held any more.
    Bluefruit.disconnect(Bluefruit.connHandle());
    delay(100);
  }

  for (uint8_t i = 0; i < NUM_KEYS; i++) {
    if (digitalRead(keys[i].pin) == LOW) {
      // A jammed key would wake us straight away and burn current through
      // its pull-up, so it is disconnected until another key wakes the remote.
      nrf_gpio_cfg_default(keys[i].pin);
    } else {
      nrf_gpio_cfg_sense_input(keys[i].pin, NRF_GPIO_PIN_PULLUP, NRF_GPIO_PIN_SENSE_LOW);
    }
  }
  NRF_GPIO->LATCH = NRF_GPIO->LATCH;  // clear stale latches before sleeping

  sd_power_system_off();  // wake-up is a reset; execution restarts in setup()
  while (true) {
    delay(1000);
  }
}

void setup() {
  // LATCH survives the System OFF wake-up reset and shows which key woke us,
  // even if it was released before the bootloader handed over.
  uint32_t latch = NRF_GPIO->LATCH;
  NRF_GPIO->LATCH = latch;

  uint32_t now = millis();
  for (uint8_t i = 0; i < NUM_KEYS; i++) {
    pinMode(keys[i].pin, INPUT_PULLUP);
  }
  delay(2);  // let pull-ups settle before the first read
  for (uint8_t i = 0; i < NUM_KEYS; i++) {
    Key &k = keys[i];
    k.stable = (digitalRead(k.pin) == LOW);
    k.since = now;
    bool woke = (latch & (1UL << k.pin)) != 0;
    // A short tap on record or centre that woke the remote still counts.
    if ((k.stable || woke) && (k.bit == KEY_CENTRE || k.bit == KEY_REC)) {
      queueClick(k.bit, now);
    }
  }
  lastActivity = now;

  // Measure the cell before the radio starts loading it.
  measureBattery();
  lastBatt = now;

  Bluefruit.begin();
  Bluefruit.autoConnLed(false);  // no LED on the remote; do not waste current
  Bluefruit.setTxPower(0);
  Bluefruit.setName("Xbot Remote");
  Bluefruit.Periph.setConnectCallback(connectCallback);
  Bluefruit.Periph.setDisconnectCallback(disconnectCallback);
  Bluefruit.Periph.setConnInterval(12, 24);  // 15..30 ms keeps key lag low

  remoteSvc.begin();
  remoteChr.setProperties(CHR_PROPS_READ | CHR_PROPS_NOTIFY);
  remoteChr.setPermission(SECMODE_OPEN, SECMODE_NO_ACCESS);
  remoteChr.setFixedLen(REPORT_LEN);
  remoteChr.begin();
  uint8_t init[REPORT_LEN] = {0, 0, 0, battPct};
  remoteChr.write(init, REPORT_LEN);

  battSvc.begin();
  battSvc.write(battPct);

  startAdvertising();
}

void loop() {
  uint32_t now = millis();

  if (now - lastScan >= SCAN_MS) {
    lastScan = now;
    scanKeys(now);
  }

  serviceReport(now);

  if (now - lastBatt >= BATT_PERIOD_MS) {
    lastBatt = now;
    measureBattery();
    battSvc.write(battPct);
  }

  // Stuck keys are excluded from heldMask, so they cannot hold the remote awake.
  if (heldMask() == 0 && pendingClicks == 0 && (now - lastActivity) > IDLE_SLEEP_MS) {
    enterSystemOff();
  }

  delay(1);  // yields to FreeRTOS so the CPU idles between scans
}
